 3	abstract class DepthFirstGraphAnalysis<Result> {
 4	    protected static final int ROOT_PARENT = -1;
 5	
 6	    private final Graph graph;
 7	    private final boolean[] visited;
 8	    private final int[] discoveryTime;
 9	    private int currentTime;
10	
11	    protected DepthFirstGraphAnalysis(Graph graph) {
12	        this.graph = Objects.requireNonNull(graph, "graph");
13	        this.discoveryTime = new int[graph.vertexCount()];
14	        this.visited = new boolean[graph.vertexCount()];
15	        this.currentTime = 0;
16	    }
17	
18	    protected final Result run() {
19	        for (int vertex = 0; vertex < graph.vertexCount(); vertex++) {
20	            if (!visited[vertex]) {
21	                depthFirstSearch(vertex, ROOT_PARENT);
22	            }
23	        }
24	
25	        return buildResult();
26	    }
27	
28	    protected final int vertexCount() {
29	        return graph.vertexCount();
30	    }
31	
32	    protected final int discoveryTimeOf(int vertex) {
33	        return discoveryTime[vertex];
34	    }
35	
36	    protected final boolean isRoot(int parent) {
37	        return parent == ROOT_PARENT;
38	    }
39	
40	    private void depthFirstSearch(int vertex, int parent) {
41	        visited[vertex] = true;
42	        discoveryTime[vertex] = ++currentTime;
43	        onDiscoverVertex(vertex, parent);
44	
45	        int childCount = 0;
46	        for (int neighbor : graph.neighborsOf(vertex)) {
47	            if (!visited[neighbor]) {
48	                childCount++;
49	                depthFirstSearch(neighbor, vertex);
50	                afterChildTraversal(vertex, neighbor, parent);
51	            } else if (neighbor != parent) {
52	                onBackEdge(vertex, neighbor);
53	            }
54	        }
55	
56	        onCompleteVertex(vertex, parent, childCount);
57	    }
58	
59	    protected void onDiscoverVertex(int vertex, int parent) {
60	    }
61	
62	    protected void afterChildTraversal(int vertex, int child, int parent) {
63	    }
64	
65	    protected void onBackEdge(int vertex, int neighbor) {
66	    }
67	
68	    protected void onCompleteVertex(int vertex, int parent, int childCount) {
69	    }
70	
71	    protected abstract Result buildResult();
72	}

