10	    private static final class ArticulationPointTraversal extends DepthFirstGraphAnalysis<List<Integer>> {
11	        private static final int NO_ARTICULATION_POINTS = -1;
12	
13	        private final int[] lowLink;
14	        private final boolean[] articulationPoint;
15	
16	        private ArticulationPointTraversal(Graph graph) {
17	            super(graph);
18	            this.lowLink = new int[vertexCount()];
19	            this.articulationPoint = new boolean[vertexCount()];
20	        }
21	
22	        @Override
23	        protected void onDiscoverVertex(int vertex, int parent) {
24	            lowLink[vertex] = discoveryTimeOf(vertex);
25	        }
26	
27	        @Override
28	        protected void afterChildTraversal(int vertex, int child, int parent) {
29	            lowLink[vertex] = Math.min(lowLink[vertex], lowLink[child]);
30	
31	            if (!isRoot(parent) && lowLink[child] >= discoveryTimeOf(vertex)) {
32	                articulationPoint[vertex] = true;
33	            }
34	        }
35	
36	        @Override
37	        protected void onBackEdge(int vertex, int neighbor) {
38	            lowLink[vertex] = Math.min(lowLink[vertex], discoveryTimeOf(neighbor));
39	        }
40	
41	        @Override
42	        protected void onCompleteVertex(int vertex, int parent, int childCount) {
43	            if (isRoot(parent) && childCount > 1) {
44	                articulationPoint[vertex] = true;
45	            }
46	        }
47	
48	        @Override
49	        protected List<Integer> buildResult() {
50	            ArrayList<Integer> result = new ArrayList<>();
51	
52	            for (int vertex = 0; vertex < articulationPoint.length; vertex++) {
53	                if (articulationPoint[vertex]) {
54	                    result.add(vertex);
